/* رسم نواة وإلكترونات على لوحة ثنائية الأبعاد */
function drawAtom2D(x,cx,cy,p,nn,o){o=o||{};var N=p+nn,r=o.r||11,pts=[],ga=Math.PI*(3-Math.sqrt(5));var R=r*Math.sqrt(N)*0.95;
  for(var i=0;i<N;i++){var rr=N===1?0:R*Math.sqrt((i+.5)/N),th=i*ga;pts.push([cx+Math.cos(th)*rr,cy+Math.sin(th)*rr])}
  var kinds=[];for(i=0;i<N;i++)kinds.push(i<p?1:0);/* توزيع منتظم */var ord=[];var a=0,b=0;for(i=0;i<N;i++){if((a/(p||1))<=(b/(nn||1))&&a<p){ord.push(1);a++}else if(b<nn){ord.push(0);b++}else{ord.push(1);a++}}
  pts.forEach(function(pt,i){var pr=ord[i];var g=x.createRadialGradient(pt[0]-r*.35,pt[1]-r*.35,1,pt[0],pt[1],r);g.addColorStop(0,pr?'#ffb0b8':'#f0f4fa');g.addColorStop(1,pr?'#d9364a':'#8f9bb0');x.fillStyle=g;x.beginPath();x.arc(pt[0],pt[1],r,0,7);x.fill();if(pr&&r>8){x.fillStyle='#fff';x.font='700 '+(r*1.1|0)+'px sans-serif';x.textAlign='center';x.textBaseline='middle';x.fillText('+',pt[0],pt[1]+1)}});
  if(o.e){var sh=[],left=o.e,cap=[2,8,8,2];for(i=0;left>0;i++){var c=Math.min(cap[i],left);sh.push(c);left-=c}var t=o.t||0;sh.forEach(function(c,k){var RR=R+(o.r1||34)+k*(o.dr||30);x.strokeStyle='rgba(127,230,255,.4)';x.lineWidth=2;x.beginPath();x.arc(cx,cy,RR,0,7);x.stroke();for(var j=0;j<c;j++){var an=j/c*Math.PI*2+t*(0.8-k*.2);var ex=cx+Math.cos(an)*RR,ey=cy+Math.sin(an)*RR;x.fillStyle='#38d6ff';x.beginPath();x.arc(ex,ey,7,0,7);x.fill();x.fillStyle='#022';x.font='700 11px sans-serif';x.textAlign='center';x.textBaseline='middle';x.fillText('−',ex,ey+1)}})}
  return R}

