     var mixc=new THREE.Group();mixc.add(new THREE.Mesh(new THREE.CylinderGeometry(.85,.75,2.2,40,1,true),new THREE.MeshStandardMaterial({color:0xcfefff,transparent:true,opacity:.25,side:THREE.DoubleSide})));var w2=new THREE.Mesh(new THREE.CylinderGeometry(.8,.72,1.5,40),new THREE.MeshStandardMaterial({color:0x6aa0c8,transparent:true,opacity:.5}));w2.position.y=-.32;mixc.add(w2);
     for(i=0;i<70;i++){var sg=new THREE.Mesh(new THREE.SphereGeometry(.06+Math.random()*.05,8,6),E.mat(0xc9a96e,{r:.9}));var a=Math.random()*6.28,r=Math.random()*.68;sg.position.set(Math.cos(a)*r,-1+Math.random()*.4,Math.sin(a)*r);mixc.add(sg)}
