     function lattice(col,rad){var g=new THREE.Group(),m=E.mat(col,{m:.5,r:.3});for(var a=0;a<3;a++)for(var b=0;b<3;b++)for(var c=0;c<3;c++){var s=new THREE.Mesh(new THREE.SphereGeometry(rad,24,18),m);s.position.set((a-1)*.62,(b-1)*.62,(c-1)*.62);g.add(s)}return g}
