     for(i=0;i<3;i++){var sand=new THREE.Group();var si=new THREE.Mesh(new THREE.SphereGeometry(.24,20,14),E.mat(0xd8b16a));sand.add(si);[-1,1].forEach(function(s){var o=new THREE.Mesh(new THREE.SphereGeometry(.2,20,14),E.mat(0xff4a4a));o.position.set(s*.32,.1,0);sand.add(o)});sand.position.set((Math.random()-.5)*1.8,(Math.random()-.5)*1.8,(Math.random()-.5)*1.1);v4.add(sand)}
