  E.problem($('#nq',el),{id:'l2-num-p',goal:2,lvl:2,q:'ذرة الكربون عددها الذري ٦ وعددها الكتلي ١٢. كم نيوترونًا في نواتها؟',a:6,label:'عدد النيوترونات',steps:'النيوترونات = A − Z = ١٢ − ٦ = ٦'});
