/* ========== ١٠) م٦ الكتلة الذرية ========== */
S({id:'mass',name:'م٦ الكتلة الذرية',build:function(el){
  el.innerHTML='<div class="eyebrow">المحطة ٦ · الكتلة الذرية ص ١١٢</div><h1 class="t" style="font-size:44px">العدد الكتلي أم الكتلة الذرية؟</h1><div class="row grow" style="min-height:0"><div class="col" style="flex:1.2;gap:10px;min-height:0"><div class="row" style="gap:12px"><div class="card grow" style="padding:12px 16px"><h3>العدد الكتلي</h3><p style="margin:0;font-size:18px">مجموع البروتونات والنيوترونات في نواة <b>نظير واحد</b>؛ عدد صحيح، مثل كلور-٣٥.</p></div><div class="card grow" style="padding:12px 16px"><h3>الكتلة الذرية</h3><p style="margin:0;font-size:18px"><b>متوسط</b> كتل نظائر العنصر حسب نسب وجودها في الطبيعة، ووحدتها <b>و.ك.ذ</b> (تساوي ١/١٢ من كتلة ذرة كربون-١٢).</p></div></div>'+
   '<div class="card" style="padding:12px 16px;flex:1;min-height:0;display:flex;flex-direction:column"><h3>مثال الكلور: ١٠٠ ذرة من عينة طبيعية</h3><div id="bag" style="display:grid;grid-template-columns:repeat(20,1fr);gap:4px;flex:1;align-content:center"></div><div class="chips" style="margin-top:8px"><span class="tag"><i style="width:12px;height:12px;border-radius:50%;background:#46d65a;display:inline-block"></i> كلور-٣٥: الكتلة ٣٤٫٩٧ و.ك.ذ</span><span class="tag gold"><i style="width:12px;height:12px;border-radius:50%;background:#1d7a2c;display:inline-block"></i> كلور-٣٧: الكتلة ٣٦٫٩٧ و.ك.ذ</span></div><div class="qa"><label style="font-size:18px">ماذا لو تغيّرت نسبة كلور-٣٥؟ <input type="range" id="ab" min="0" max="100" value="76" style="width:260px;vertical-align:middle"></label><b class="num" id="abv" style="font-size:20px"></b></div><p class="hint" style="margin:0">النسبة الحقيقية في الطبيعة: كلور-٣٥ ٧٥٫٨٪ وكلور-٣٧ ٢٤٫٢٪.</p></div></div>'+
   '<div class="col grow side" style="gap:10px"><div class="card" style="padding:12px 16px"><div style="display:flex;align-items:center;gap:14px"><div style="width:120px;height:130px;border-radius:16px;border:3px solid var(--ok);display:flex;flex-direction:column;align-items:center;justify-content:space-between;padding:8px;flex:0 0 auto"><span class="num">١٧</span><b style="font-family:var(--disp);font-size:44px;line-height:1">Cl</b><span class="num gl" id="avg">٣٥٫٤٥</span></div><div style="font-size:18px;line-height:1.8">الكتلة الذرية = (كتلة النظير الأول × نسبته) + (كتلة النظير الثاني × نسبته)</div></div></div><div class="card reveal" style="padding:12px 16px"><div class="explain" style="font-size:18px">(٣٤٫٩٧ × ٠٫٧٥٨) + (٣٦٫٩٧ × ٠٫٢٤٢)<br>= ٢٦٫٥١ + ٨٫٩٥ = <b>٣٥٫٤٥ و.ك.ذ</b><br>لذلك لا تكون الكتلة الذرية عددًا صحيحًا غالبًا، وتكون أقرب إلى كتلة النظير الأكثر وجودًا.</div></div><div id="mq"></div></div></div>';
  function upd(){var a=+$('#ab',el).value;var v=(34.97*a+36.97*(100-a))/100;$('#abv',el).textContent=n(a)+'٪ ← المتوسط ≈ '+n(v.toFixed(2));$('#bag',el).innerHTML=Array.from({length:100},function(_,i){return '<i style="aspect-ratio:1;border-radius:50%;background:'+(i<a?'#46d65a':'#1d7a2c')+';box-shadow:inset -3px -3px 6px rgba(0,0,0,.3)"></i>'}).join('')}
  $('#ab',el).oninput=function(){upd();E.complete('mass')};upd();
  E.problem($('#mq',el),{id:'l2-mass-p',goal:2,lvl:3,q:'احسب الكتلة الذرية للكلور: (٣٤٫٩٧ × ٠٫٧٥٨) + (٣٦٫٩٧ × ٠٫٢٤٢) = ؟',a:35.45,tol:0.02,unit:'و.ك.ذ',steps:'٢٦٫٥١ + ٨٫٩٥ = ٣٥٫٤٥ و.ك.ذ'});
  E.mcq($('#mq',el),{id:'l2-mass-q',goal:2,lvl:2,q:'متوسط كتل نظائر العنصر الواحد حسب نسب وجودها هو:',o:['العدد الذري','العدد الكتلي','الكتلة الذرية','عدد النيوترونات'],a:2,cols:2,ex:'الكتلة الذرية متوسط كتل النظائر، أما العدد الكتلي فيخص نظيرًا واحدًا.'});
  return {}}});

