  function tk(k,s,nm){return {t:'<b class="num" style="font-family:var(--disp)">'+s+'</b> '+nm,img:k?img(k):'',b:0}}
  var items=[['u_ironwire','Fe','الحديد',0],['u_cuwire','Cu','النحاس',0],['u_goldbar','Au','الذهب',0],['u_alpot','Al','الألومنيوم',0],['u_carbon','C','الكربون',1],['e_s','S','الكبريت',1],['u_cl','Cl','الكلور',1],['','O','الأكسجين',1],['u_chip','Si','السيليكون',2],['','B','البورون',2],['','Ge','الجرمانيوم',2]].map(function(a){var o=tk(a[0],a[1],a[2]);o.b=a[3];return o});
